{"content":"#!/usr/bin/env python3
"""Revert a resharded directory back to its original layout, in place.

Usage:
    python /app/decompress.py <resharded_dir>

The manifest is loaded fully into memory before anything is written, so a
restored original file may safely occupy the manifest's own path. Every
shard tar is opened read-only and each member is streamed straight to its
destination file; nothing is held fully in memory.
"""

import json
import os
import shutil
import sys
import tarfile

MANIFEST_NAME = ".reshard_manifest.json"
COPY_BUFSIZE = 1024 * 1024


def fail(message):
    print("error: %s" % message, file=sys.stderr)
    return 1


def dest_path(root, rel):
    parts = rel.split("/")
    if any(p in ("", ".", "..") for p in parts):
        raise ValueError("unsafe path in manifest: %r" % rel)
    return os.path.join(root, *parts)


def ensure_parent(path):
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)


def stream_member_to_file(tar, member, out_path, append=False):
    ensure_parent(out_path)
    src = tar.extractfile(member)
    if src is None:
        raise ValueError("cannot extract member %r" % member.name)
    mode = "ab" if append else "wb"
    try:
        with open(out_path, mode) as dst:
            shutil.copyfileobj(src, dst, COPY_BUFSIZE)
    finally:
        src.close()


def load_manifest(target):
    manifest_path = os.path.join(target, MANIFEST_NAME)
    if not os.path.isfile(manifest_path):
        return None, None
    with open(manifest_path, "rb") as fh:
        raw_manifest = fh.read()
    try:
        manifest = json.loads(raw_manifest.decode("utf-8"))
    except (ValueError, UnicodeDecodeError):
        raise ValueError("manifest %r is not valid JSON" % manifest_path)
    if not isinstance(manifest, dict) or manifest.get("version") != 1:
        raise ValueError("unsupported manifest format in %r" % manifest_path)
    parts = manifest.get("manifest_parts")
    if parts:
        files = []
        base = None
        for part_rel in parts:
            part_path = dest_path(target, part_rel)
            with open(part_path, "rb") as fh:
                part = json.load(fh)
            if base is None:
                base = {k: v for k, v in part.items() if k != "files"}
            files.extend(part.get("files", []))
        full = dict(base or {})
        full["files"] = files
        full["manifest_parts"] = parts
        if "manifest_overwrote_original" not in full:
            full["manifest_overwrote_original"] = manifest.get(
                "manifest_overwrote_original", False)
        manifest = full
    return manifest, raw_manifest


def remove_empty_dirs_upward(start_dir, stop_dir):
    current = os.path.abspath(start_dir)
    stop = os.path.abspath(stop_dir)
    while current.startswith(stop) and len(current) > len(stop):
        try:
            os.rmdir(current)
        except OSError:
            break
        current = os.path.dirname(current)


def main(argv=None):
    args = argv if argv is not None else sys.argv[1:]
    if len(args) != 1 or args[0] in ("-h", "--help"):
        print("usage: python decompress.py <resharded_dir>")
        return 0 if args and args[0] in ("-h", "--help") else 2
    target = os.path.abspath(args[0])
    if not os.path.isdir(target):
        return fail("not a directory: %s" % args[0])

    try:
        loaded = load_manifest(target)
    except (OSError, ValueError) as exc:
        return fail(str(exc))
    manifest, raw_manifest = loaded
    if manifest is None:
        return fail("no %s found in %s; not a resharded directory"
                    % (MANIFEST_NAME, args[0]))

    files = manifest.get("files", [])
    shards = manifest.get("shards", [])
    dirs = manifest.get("dirs", [])
    symlinks = manifest.get("symlinks", [])
    part_paths = manifest.get("manifest_parts", [])

    # Group plain (non-chunked) members by shard so each tar is opened once.
    by_shard = {}
    chunked = []
    for entry in files:
        if "chunks" in entry:
            chunked.append(entry)
            continue
        by_shard.setdefault(entry["shard"], []).append(entry)

    open_tars = {}

    def get_tar(shard_rel):
        tar = open_tars.get(shard_rel)
        if tar is None:
            tar_path = dest_path(target, shard_rel)
            tar = tarfile.open(tar_path, "r")
            open_tars[shard_rel] = tar
        return tar

    total = 0
    try:
        # Plain files, shard by shard.
        for shard_rel in shards:
            members = by_shard.get(shard_rel)
            if not members:
                # Still open the tar so a corrupt shard is noticed.
                get_tar(shard_rel)
                continue
            tar = get_tar(shard_rel)
            index = {m.name: m for m in tar.getmembers()}
            for entry in members:
                member = index.get(entry["member"])
                if member is None or not member.isfile():
                    raise ValueError(
                        "member %r missing in shard %r"
                        % (entry["member"], shard_rel))
                out_path = dest_path(target, entry["path"])
                stream_member_to_file(tar, member, out_path)
                total += 1
        # Large files split across chunks, reassembled in index order.
        for entry in chunked:
            out_path = dest_path(target, entry["path"])
            ensure_parent(out_path)
            with open(out_path, "wb") as _dst:
                pass
            for chunk in sorted(entry["chunks"], key=lambda c: c["index"]):
                tar = get_tar(chunk["shard"])
                member = tar.getmember(chunk["member"])
                if not member.isfile():
                    raise ValueError(
                        "member %r missing in shard %r"
                        % (chunk["member"], chunk["shard"]))
                stream_member_to_file(tar, member, out_path, append=True)
            total += 1
    except (OSError, ValueError, tarfile.TarError, KeyError) as exc:
        for tar in open_tars.values():
            try:
                tar.close()
            except OSError:
                pass
        return fail("extraction failed: %s" % exc)
    finally:
        for tar in open_tars.values():
            try:
                tar.close()
            except OSError:
                pass

    # Recreate directories (covers empty ones), symlinks, and metadata.
    try:
        for rel in dirs:
            os.makedirs(dest_path(target, rel), exist_ok=True)
        for link in symlinks:
            link_path = dest_path(target, link["path"])
            ensure_parent(link_path)
            try:
                if os.path.islink(link_path) or os.path.exists(link_path):
                    os.remove(link_path)
            except OSError:
                pass
            os.symlink(link["target"], link_path)
        for entry in files:
            if entry.get("mode") is None:
                continue
            try:
                os.chmod(dest_path(target, entry["path"]),
                         entry["mode"] & 0o7777)
            except OSError:
                pass
        for entry in files:
            if entry.get("mtime_ns") is None:
                continue
            try:
                os.utime(dest_path(target, entry["path"]),
                         ns=(entry["mtime_ns"], entry["mtime_ns"]))
            except OSError:
                pass
    except OSError as exc:
        return fail("failed to restore structure: %s" % exc)

    # Remove resharding artefacts. Shard paths are guaranteed distinct from
    # original paths (compress enforces this), so deleting them is safe.
    for shard_rel in shards:
        try:
            os.remove(dest_path(target, shard_rel))
        except OSError as exc:
            return fail("cannot remove shard %r: %s" % (shard_rel, exc))
    for part_rel in part_paths:
        try:
            os.remove(dest_path(target, part_rel))
        except OSError as exc:
            return fail("cannot remove manifest part %r: %s"
                        % (part_rel, exc))
    for shard_rel in shards:
        remove_empty_dirs_upward(
            os.path.dirname(dest_path(target, shard_rel)), target)
    if part_paths:
        remove_empty_dirs_upward(
            os.path.dirname(dest_path(target, part_paths[0])), target)

    # The manifest path itself may have been an original file (compress
    # records this and its bytes were already restored above). Only delete
    # the manifest when it is still ours.
    if manifest.get("manifest_overwrote_original"):
        pass
    else:
        manifest_path = os.path.join(target, MANIFEST_NAME)
        try:
            with open(manifest_path, "rb") as fh:
                current = fh.read()
        except OSError:
            current = None
        if current == raw_manifest:
            try:
                os.remove(manifest_path)
            except OSError as exc:
                return fail("cannot remove manifest: %s" % exc)

    print("decompressed %d file(s) in-place in %s (%d byte(s) restored)"
          % (len(files), args[0], sum(int(e.get("size", 0)) for e in files)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
